Translate("ptBR", "darnassus", {
	title = "Darnassus",
	sections = {
		{
			title = "Resumo",
			text = [=[Darnassus é a capital dos {link:night-elves}elfos noturnos{/link}, uma cidade de madeira viva e águas enluaradas nos altos ramos de {link:teldrassil}Teldrassil{/link}. Seus salões foram cultivados, não construídos. Seus terraços se abrem para jardins e lagos tranquilos, e o {link:temple-of-the-moon}Templo da Lua{/link} brilha em seu coração. É uma cidade jovem de um povo antigo. Os kaldorei a ergueram depois da {link:third-war}Terceira Guerra{/link}, quando haviam perdido a imortalidade e seu antigo lar no {link:mount-hyjal}Monte Hyjal{/link} jazia marcado, e quiseram que ela fosse um novo começo.]=],
		},
		{
			title = "Origens",
			text = [=[Quando a guerra contra a {link:burning-legion}Legião Ardente{/link} terminou, o Arquidruida {link:fandral-staghelm}Fandral Staghelm{/link} e seus druidas fizeram crescer {link:teldrassil}Teldrassil{/link} além da costa norte. Darnassus surgiu em sua copa. As sacerdotisas de Eluna instalaram ali seu templo, os druidas seu enclave e as {link:sentinels}Sentinelas{/link} seus quartéis. Da {link:rut-theran-village}Vila de Rut'theran{/link}, muito abaixo, um portal leva os viajantes até a cidade.]=],
		},
		{
			title = "Os Dias de Hoje",
			text = [=[Dois líderes têm assento em Darnassus. A {link:tyrande-whisperwind}Suma Sacerdotisa Tyrande Whisperwind{/link} governa a cidade e seu povo segundo a vontade de Eluna. {link:fandral-staghelm}Fandral Staghelm{/link} lidera os druidas na longa ausência de {link:malfurion-stormrage}Malfurion Stormrage{/link}, que não voltou do {link:emerald-dream}Sonho Esmeralda{/link}. Tyrande pede a seu povo que respeite a posição dele, mas lembra que os assuntos de Darnassus pertencem só a ela. Fandral, por sua vez, não confia em ninguém de fora de seu enclave. Ele e o {link:keeper-remulos}Guardião Remulos{/link}, da {link:moonglade}Clareira da Lua{/link}, suspeitam um do outro, e os males da Árvore do Mundo seguem sem cura. As {link:sentinels}Sentinelas{/link} mantêm uma vigilância atenta dentro da própria cidade, pois algo está errado em {link:teldrassil}Teldrassil{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}As sacerdotisas de Eluna.{/b} Cuidam do {link:temple-of-the-moon}Templo da Lua{/link} e curam os {link:night-elves}kaldorei{/link}.
• {b}Os druidas do {link:cenarion-circle}Círculo Cenariano{/link}.{/b} Estudam no {link:cenarion-enclave}Enclave Cenariano{/link} sob o Arquidruida.
• {b}As {link:sentinels}Sentinelas{/link}.{/b} As guerreiras que guardam a cidade e as florestas além dela.
• {b}Aliados da {link:alliance}Aliança{/link}.{/b} Estudiosos anões da {link:explorers-league}Liga dos Exploradores{/link} e emissários da {link:argent-dawn}Aurora Argêntea{/link} vieram à cidade.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Fundação.{/b} A cidade foi erguida nos ramos da nova Árvore do Mundo depois da {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}.
• {b}Os Poços Lunares.{/b} Os druidas da cidade recorrem aos poços lunares de {link:teldrassil}Teldrassil{/link}, e mensageiros trazem frascos de sua água de {link:shadowglen}Umbravale{/link}, {link:dolanaar}Dolanaar{/link} e da {link:the-oracle-glade}Clareira do Oráculo{/link}.
• {b}A Ruptura com a {link:moonglade}Clareira da Lua{/link}.{/b} O Arquidruida e o {link:keeper-remulos}Guardião Remulos{/link} se afastaram, e os druidas da cidade servem ao Círculo sob uma nuvem de suspeita.
• {b}Os Dias de Hoje.{/b} Os {link:night-elves}kaldorei{/link} se juntaram à {link:alliance}Aliança{/link}, e heróis de todos os povos agora caminham pelos terraços de Darnassus.]=],
		},
		{
			title = "Saber da Cidade",
			text = [=[• Uma fonte no coração do {link:temple-of-the-moon}Templo da Lua{/link} guarda água sagrada que, dizem, purifica o que toca.
• A árvore do Arquidruida fica no {link:cenarion-enclave}Enclave Cenariano{/link}, e túneis correm por baixo dela.
• Os druidas de Darnassus estudam o solo trazido da distante {link:un-goro-crater}Cratera Un'Goro{/link}, e cultivam nele ervas cuja natureza ainda não compreendem.]=],
		},
	},
})

Translate("ptBR", "temple-of-the-moon", {
	title = "Templo da Lua",
	aliases = { "Jardins do Templo" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Templo da Lua ergue-se entre os Jardins do Templo, no sul de {link:darnassus}Darnassus{/link}. É a casa de Eluna e a sede da Suma Sacerdotisa. {link:tyrande-whisperwind}Tyrande Whisperwind{/link} recebe a corte em seu salão superior. Embaixo, as sacerdotisas ensinam os jovens e curam os feridos, e uma fonte de água sagrada jorra em seu centro. As oferendas depositadas nessa fonte são entregues à deusa. {link:sentinels}Sentinelas{/link} guardam suas portas e rezam ali todos os dias, pois uma caçadora de Eluna deve empunhar os dons da deusa tão bem quanto a lâmina.]=],
		},
	},
})

Translate("ptBR", "cenarion-enclave", {
	title = "Enclave Cenariano",
	sections = {
		{
			title = "Resumo",
			text = [=[O Enclave Cenariano é o bairro dos druidas, no norte de {link:darnassus}Darnassus{/link}. Ali cresce a grande árvore do {link:fandral-staghelm}Arquidruida Fandral Staghelm{/link}, onde ele estuda os males de {link:teldrassil}Teldrassil{/link} com seu imediato, {link:mathrengyl-bearwalker}Mathrengyl Bearwalker{/link}, no andar de baixo. Druidas como {link:rellian-greenspyre}Rellian Greenspyre{/link} percorrem seus caminhos. Caçadores e ladinos também têm salões ali. Atrás da árvore do Arquidruida, montes de um solo estranho de terras distantes esperam para ser separados, e túneis descem para as profundezas sob o Enclave.]=],
		},
	},
})

Translate("ptBR", "warriors-terrace", {
	title = "Terraço dos Guerreiros",
	sections = {
		{
			title = "Resumo",
			text = [=[O Terraço dos Guerreiros fica no leste de {link:darnassus}Darnassus{/link}. Ali os guerreiros {link:night-elves}kaldorei{/link} treinam com mestres como Elanaria e Arias'ta Bladesinger, e ali a comandante {link:thyn-tel-bladeweaver}Thyn'tel Bladeweaver{/link} cuida dos assuntos das {link:sentinels}Sentinelas{/link}. Os pertences das Sentinelas desaparecidas ficam guardados em seu alojamento até que voltem. Uma guerreira que queira aprender mais deve primeiro provar sua determinação contra os inimigos da árvore.]=],
		},
	},
})

Translate("ptBR", "craftsmens-terrace", {
	title = "Terraço dos Artesãos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Terraço dos Artesãos fica no nordeste de {link:darnassus}Darnassus{/link}. Coureiros, alfaiates e outros artesãos {link:night-elves}kaldorei{/link} mantêm ali suas oficinas, e a estalagem da cidade oferece descanso a viajantes de todas as terras. Emissários da {link:argent-dawn}Aurora Argêntea{/link} se instalaram entre os artesãos. O tecido da {link:alliance}Aliança{/link} também é reunido ali, para as necessidades da guerra que virá.]=],
		},
	},
})

Translate("ptBR", "tradesmens-terrace", {
	title = "Terraço dos Mercadores",
	sections = {
		{
			title = "Resumo",
			text = [=[O Terraço dos Mercadores fica no leste de {link:darnassus}Darnassus{/link}, entre os jardins e o {link:warriors-terrace}Terraço dos Guerreiros{/link}. É o mercado da cidade. Vendedores de comida, tecido, armas e mercadorias em geral mantêm suas bancas ao longo de seus caminhos sinuosos, e as notícias da floresta lá embaixo correm depressa entre eles. É o lugar mais movimentado de Darnassus, e ainda assim mais tranquilo que qualquer mercado das terras humanas.]=],
		},
	},
})

Translate("ptBR", "tyrande-whisperwind", {
	title = "Tyrande Whisperwind",
	subtitle = "Suma Sacerdotisa de Eluna",
	found = "O salão superior do Templo da Lua",
	hint = [=[Suba ao salão superior do Templo da Lua e procure a Suma Sacerdotisa.]=],
	allegiance = "Elfos Noturnos · Irmandade de Eluna · Sentinelas",
	aliases = { "Tyrande", "Suma Sacerdotisa Tyrande Whisperwind" },
	sections = {
		{
			title = "Resumo",
			text = [=[Tyrande Whisperwind é a Suma Sacerdotisa de Eluna e a líder dos elfos noturnos. Há dez mil anos ela protege seu povo, primeiro nas ruínas de seu antigo império e agora nos ramos de {link:teldrassil}Teldrassil{/link}. É a amada de {link:malfurion-stormrage}Malfurion Stormrage{/link}, e espera a volta dele. Governa {link:darnassus}Darnassus{/link} com firmeza, e é conhecida por sua bondade.]=],
		},
		{
			title = "Importância",
			text = [=[Tyrande é o laço vivo entre os {link:night-elves}kaldorei{/link} de outrora e os kaldorei de hoje. Lutou na {link:war-of-the-ancients}Guerra dos Antigos{/link} e na {link:third-war}Terceira Guerra{/link}. Sob ela, as {link:sentinels}Sentinelas{/link} se tornaram o escudo de seu povo, e sob ela os elfos noturnos se juntaram à {link:alliance}Aliança{/link}.]=],
		},
		{
			title = "História",
			text = [=[Tyrande era noviça da Irmandade de Eluna nos dias da {link:queen-azshara}Rainha Azshara{/link}. Os irmãos gêmeos {link:malfurion-stormrage}Malfurion{/link} e {link:illidan-stormrage}Illidan Stormrage{/link} a amavam, e ela escolheu Malfurion. Quando a {link:burning-legion}Legião Ardente{/link} chegou, ela lutou ao lado deles, e ascendeu à liderança da Irmandade naquela guerra. Depois da {link:great-sundering}Grande Cisão{/link}, enquanto os druidas dormiam no {link:emerald-dream}Sonho Esmeralda{/link}, ela e suas sacerdotisas vigiaram as florestas por longos séculos.

Quando a Legião voltou e os humanos e orcs chegaram a {link:kalimdor}Kalimdor{/link}, Tyrande despertou os druidas adormecidos de suas grutas. Libertou Illidan de sua prisão, contra a vontade de seu amado. Na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, suas {link:sentinels}Sentinelas{/link} lutaram ao lado de humanos e orcs até a queda de {link:archimonde}Archimonde{/link}.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} entrou outra vez no Sonho, e ninguém sabe o que foi feito dele. Tyrande lidera os {link:night-elves}kaldorei{/link} sozinha. Respeita {link:fandral-staghelm}Fandral Staghelm{/link} como Arquidruida, mas não o deixa esquecer que o domínio dele é o druidismo, enquanto o dela é o seu povo inteiro. Suas sacerdotisas e {link:sentinels}Sentinelas{/link} lhe trazem notícias de todas as florestas de {link:kalimdor}Kalimdor{/link}, e ela mesma as ouve. Os que chegam a seu templo com feitos realizados por seu povo a encontram grata e generosa, e pronta a pedir que compartilhem suas histórias com os jovens.]=],
		},
	},
	chapters = {
		{
			title = "A Água dos Poços Lunares",
			hint = [=[Leve o que resta da água dos poços lunares à Suma Sacerdotisa.]=],
			text = [=[As últimas gotas da água dos poços lunares chegaram a Tyrande num recipiente cerimonial, depois que o Arquidruida as rejeitou. Ela agradeceu a quem as trouxe, pois cada gota era abençoada por Eluna. Falou também, breve e duramente, de {link:fandral-staghelm}Fandral{/link}: ele havia feito muito na ausência de {link:malfurion-stormrage}Malfurion{/link}, mas não era Malfurion.]=],
		},
		{
			title = "Notícias das Terras Selvagens",
			hint = [=[Leve à Suma Sacerdotisa notícias de suas sacerdotisas e batedoras em terras distantes.]=],
			text = [=[Notícias chegam ao templo de todos os cantos de {link:kalimdor}Kalimdor{/link}: das {link:sentinels}Sentinelas{/link} da {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link} e da sacerdotisa {link:jer-kai-moonweaver}Jer'kai{/link}, que combate {link:grimtotem-clan}os Temível Totem{/link} em {link:feralas}Feralas{/link}. Tyrande ouve cada relato ela mesma, e envia suas batedoras aonde são necessárias.]=],
		},
	},
	mentions = {
		{ text = "Recepção de Tyrande" },
		{ text = "Fazendo Justiça" },
		{ text = "Explorando a {link:alliance}Aliança{/link}" },
		{ text = "Coroa da Terra" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "seu amado" },
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "o irmão que ela libertou" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "Arquidruida de seu povo" },
		{ id = "sentinels", name = "Sentinelas", note = "suas guardiãs" },
		{ id = "priestess-a-moora", name = "Sacerdotisa A'moora", note = "serve em seu templo" },
	},
})

Translate("ptBR", "fandral-staghelm", {
	title = "Fandral Staghelm",
	subtitle = "Arquidruida de Darnassus",
	found = "Sua árvore no Enclave Cenariano",
	hint = "Procure o Arquidruida em sua árvore no Enclave Cenariano.",
	allegiance = "Elfos Noturnos · Círculo Cenariano",
	aliases = { "Fandral", "Arquidruida Fandral Staghelm" },
	sections = {
		{
			title = "Resumo",
			text = [=[Fandral Staghelm é o Arquidruida dos elfos noturnos. Quando {link:malfurion-stormrage}Malfurion Stormrage{/link} desapareceu depois da {link:third-war}Terceira Guerra{/link}, Fandral assumiu a liderança dos druidas e decidiu que seu povo iria se reconstruir. Fez crescer {link:teldrassil}Teldrassil{/link}, a nova Árvore do Mundo, e ainda trabalha para torná-la íntegra. É orgulhoso, impaciente e incansável, e não confia em ninguém além de si mesmo para terminar a obra.]=],
		},
		{
			title = "Importância",
			text = [=[Poucos {link:night-elves}kaldorei{/link} moldaram mais a era presente que Fandral. {link:darnassus}Darnassus{/link} se ergue na árvore que ele criou. Mas a árvore tem falhas, a imortalidade que ele buscava não voltou, e sua disputa com a {link:moonglade}Clareira da Lua{/link} divide o {link:cenarion-circle}Círculo Cenariano{/link}.]=],
		},
		{
			title = "História",
			text = [=[Depois da {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, {link:nordrassil}Nordrassil{/link} jazia fumegante e os druidas estavam sem líder. Fandral convenceu o Círculo dos Anciãos, na {link:darkshore}Costa Negra{/link}, de que os {link:night-elves}kaldorei{/link} precisavam se reconstruir e reconquistar a imortalidade. Com a aprovação do Círculo, ele e os druidas mais poderosos fizeram crescer {link:teldrassil}Teldrassil{/link} ao largo da costa norte. Depois pediu a bênção dos dragões. Nozdormu recusou e repreendeu sua arrogância, e {link:alexstrasza}Alexstrasza{/link} também recusou. Sem os dons deles, a árvore cresceu com falhas e imprevisível.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Fandral trabalha sem descanso nos problemas da árvore, e os chama de um jugo do qual deseja se livrar. Acredita que só ele tirou seu povo das trevas, e chama as palavras da {link:moonglade}Clareira da Lua{/link} de propaganda. Ele e o {link:keeper-remulos}Guardião Remulos{/link} suspeitam um do outro. Até seu próprio imediato admite que o ar entre os dois é pesado de desconfiança.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele fez crescer {link:teldrassil}Teldrassil{/link}, a nova Árvore do Mundo.
• Ele estuda os solos de {link:un-goro-crater}Un'Goro{/link} e a erva grão-da-manhã.
• Ele envia mensagens a {link:onu}Onu{/link}, o Anciente do Saber na {link:darkshore}Costa Negra{/link}.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Pouco se escreveu sobre a vida de Fandral antes da {link:third-war}Terceira Guerra{/link}. Este verbete registra apenas seus feitos desde então.]=],
		},
	},
	chapters = {
		{
			title = "A Coroa da Terra",
			hint = "Leve ao Arquidruida a água dos poços lunares de Teldrassil.",
			text = [=[O recipiente enchido nos poços lunares da árvore chegou enfim a Fandral. Ele resmungou que havia demorado demais e que os mensageiros não eram os mais confiáveis. Depois falou do peso dos problemas de {link:teldrassil}Teldrassil{/link} sobre seus ombros.]=],
		},
		{
			title = "O Relatório do Oráculo",
			hint = "Entregue ao Arquidruida o relatório da Árvore do Oráculo.",
			text = [=[A Árvore do Oráculo estava calada havia muito tempo. Seu relatório contou a Fandral que alguns males da árvore haviam diminuído, enquanto outros haviam crescido. Ele temeu em voz alta que sua obra nunca estaria terminada.]=],
		},
		{
			title = "A Nova Fronteira",
			hint = "Atenda ao pedido de ajuda do Círculo Cenariano.",
			text = [=[Quando a {link:moonglade}Clareira da Lua{/link} pediu ajuda no extremo oeste, Fandral passou o assunto a {link:mathrengyl-bearwalker}Mathrengyl{/link} de má vontade, e deu um aviso seu: não ser tolo de acreditar nas palavras da Clareira da Lua.]=],
		},
	},
	mentions = {
		{ text = "Coroa da Terra" },
		{ text = "{link:teldrassil}Teldrassil{/link}" },
		{ text = "{link:grove-of-the-ancients}Bosque dos Ancientes{/link}" },
		{ text = "A Nova Fronteira" },
		{ text = "Solo de {link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Pesquisa do Grão-da-manhã" },
		{ text = "Selvagens de Eluna" },
		{ text = "Coroa da Terra, o frasco que ele rejeitou" },
	},
	bonds = {
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "lidera os druidas em seu lugar" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "governa a cidade que ele ergueu" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "seu imediato" },
		{ id = "corithras-moonrage", name = "Corithras Moonrage", note = "envia-lhe a água dos poços lunares" },
	},
})

