	sections = {
		{
			title = "Resumo",
			text = [=[Mathrengyl Bearwalker é o assistente direto do Arquidruida, um dos druidas mais sábios de {link:teldrassil}Teldrassil{/link}. Ele treina jovens druidas e os envia à {link:moonglade}Clareira da Lua{/link}, sejam quais forem as disputas dos mais velhos. É honesto sobre essas disputas. A desconfiança entre {link:darnassus}Darnassus{/link} e a Clareira da Lua é real, admite, mas o dever para com o Círculo permanece.]=],
		},
