			title = "Feitos",
			text = [=[• Ele ensina jovens druidas e os envia ao {link:nighthaven}Refúgio Noturno{/link}.
• Ele atende aos pedidos de ajuda da {link:moonglade}Clareira da Lua{/link} quando o Arquidruida não atende.
• Ele supervisiona o cultivo do grão-da-manhã.]=],
		},
	},
	mentions = {
		{ text = "Atendendo ao Chamado" },
		{ text = "{link:moonglade}Clareira da Lua{/link}" },
		{ text = "A Nova Fronteira" },
