Translate("ptBR", "sentinels", {
	title = "Sentinelas",
	sections = {
		{
			title = "Resumo",
			text = [=[As Sentinelas são as guerreiras dos {link:night-elves}elfos noturnos{/link}. Há milhares de anos guardam as florestas de {link:kalimdor}Kalimdor{/link}, e respondem à Suma Sacerdotisa de Eluna. A maioria é de mulheres, caçadoras que empunham os dons da deusa tão bem quanto a glaive e o arco.]=],
		},
		{
			title = "Origens",
			text = [=[Depois da {link:great-sundering}Grande Cisão{/link}, enquanto os druidas dormiam no {link:emerald-dream}Sonho Esmeralda{/link}, as sacerdotisas de Eluna e suas guerreiras vigiaram os {link:night-elves}kaldorei{/link}. Ao longo dessas longas eras, as Sentinelas se tornaram o escudo de seu povo.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Sentinelas montam guarda em cada aldeia de {link:teldrassil}Teldrassil{/link} e em cada estrada. Guardam a Árvore do Oráculo, levam suas mensagens a {link:darnassus}Darnassus{/link} e combatem os {link:gnarlpine-furbolgs}Masca-pinho{/link} e as harpias. Além da árvore, mantêm postos na {link:darkshore}Costa Negra{/link}, no {link:ashenvale}Vale Gris{/link} e em {link:feralas}Feralas{/link}. A {link:shandris-feathermoon}General Feathermoon{/link} cuida para que cada uma delas tenha tempo para orar, e em Darnassus elas vigiam a própria cidade, pois temem que algo esteja errado.]=],
		},
	},
})
